  j constant jsonb := $j$[
{"id":"8217ebbf-bb92-43e4-b5e8-9d3e380a6e98","recipe_group_id":"24670f80-3bbf-468c-b93a-6e1780efea48","language":"es","slug":"estofado-de-res-con-papas-y-zanahorias","public_path":"/estofado-de-res-con-papas-y-zanahorias","source_url":null,"title":"Estofado de res con papas y zanahorias","excerpt":"Estofado de res con papas y zanahorias, cocido a fuego lento hasta que la carne queda tierna y la salsa espesa. Para 4 personas, listo en 2 horas y 10 minutos.","summary":"El estofado de res con papas y zanahorias se prepara dorando la carne en cubos, sofriendo cebolla, ajo y pasta de tomate, y cociéndola a fuego lento en caldo con laurel y tomillo hasta que esté tierna. Después se añaden las papas y las zanahorias y se espesa la salsa destapando la olla.\n\nEl estofado tarda 2 horas y 10 minutos entre preparación y cocción, casi todo sin supervisión. Rinde 4 porciones.","category":"Platos principales","difficulty":"Media","course":"Plato principal","cuisine":"Latinoamericana","prep_time_minutes":20,"cook_time_minutes":110,"total_time_minutes":130,"servings":4,"keywords":["estofado de res","estofado de res con papas y zanahorias","receta de estofado de carne","cómo hacer estofado de res","estofado de carne con verduras","guiso de res con papas","estofado de res tierno"],"ingredients":[{"name":"carne de res para estofar, en cubos","amount":"800","unit":"g","group":"Para el estofado"},{"name":"cebolla","amount":"1","unit":"","group":"Para el estofado"},{"name":"dientes de ajo","amount":"3","unit":"","group":"Para el estofado"},{"name":"aceite de oliva","amount":"2","unit":"cucharada","group":"Para el estofado"},{"name":"pasta de tomate","amount":"1","unit":"cucharada","group":"Para el estofado"},{"name":"caldo de res","amount":"800","unit":"ml","group":"Para el estofado"},{"name":"hoja de laurel","amount":"1","unit":"","group":"Para el estofado"},{"name":"ramita de tomillo","amount":"1","unit":"","group":"Para el estofado"},{"name":"sal","amount":"1","unit":"cucharadita","group":"Para el estofado"},{"name":"pimienta negra molida","amount":"1","unit":"pizca","group":"Para el estofado"},{"name":"papas","amount":"3","unit":"","group":"Para las verduras"},{"name":"zanahorias","amount":"3","unit":"","group":"Para las verduras"},{"name":"perejil picado","amount":"1","unit":"cucharada","group":"Para servir"}],"steps":[{"title":"Prepara los ingredientes","content":"Seca 800 g de carne de res en cubos con papel de cocina y sazónala con 1 cucharadita de sal y 1 pizca de pimienta. Pica 1 cebolla y 3 dientes de ajo, y pela 3 papas y 3 zanahorias y córtalas en trozos grandes.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-01.webp","image_alt":"Estofado de res con papas y zanahorias: Prepara los ingredientes"},{"title":"Dora la carne","content":"Calienta 2 cucharadas de aceite en una olla grande a fuego medio-alto y dora la carne en tandas, sin amontonarla, durante 8 minutos en total. Al terminar, vuelve a poner toda la carne en la olla.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-02.webp","image_alt":"Estofado de res con papas y zanahorias: Dora la carne"},{"title":"Sofríe la cebolla y el ajo","content":"Baja a fuego medio, añade la cebolla, el ajo y 1 cucharada de pasta de tomate, y sofríe 3 minutos removiendo.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-03.webp","image_alt":"Estofado de res con papas y zanahorias: Sofríe la cebolla y el ajo"},{"title":"Cuece a fuego lento","content":"Vierte 800 ml de caldo de res, añade 1 hoja de laurel y 1 ramita de tomillo, tapa la olla y cuece a fuego bajo 60 minutos.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-04.webp","image_alt":"Estofado de res con papas y zanahorias: Cuece a fuego lento"},{"title":"Añade las verduras","content":"Incorpora las papas y las zanahorias, tapa y cuece 30 minutos más, hasta que estén tiernas.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-05.webp","image_alt":"Estofado de res con papas y zanahorias: Añade las verduras"},{"title":"Espesa la salsa","content":"Destapa la olla y cuece 10 minutos a fuego medio-bajo, hasta que la salsa se espese.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-06.webp","image_alt":"Estofado de res con papas y zanahorias: Espesa la salsa"},{"title":"Rectifica la sazón","content":"Prueba y rectifica de sal y pimienta. Retira la hoja de laurel y la ramita de tomillo.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-07.webp","image_alt":"Estofado de res con papas y zanahorias: Rectifica la sazón"},{"title":"Sirve","content":"Sirve caliente en platos hondos, con 1 cucharada de perejil picado por encima.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-08.webp","image_alt":"Estofado de res con papas y zanahorias: Sirve"}],"image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/portada.webp","gallery":[{"url":"/recetas/estofado-de-res-con-papas-y-zanahorias/portada.webp","alt":"Estofado de res con papas y zanahorias"}],"notes":"Elige una carne para estofar, con algo de grasa y tejido conectivo (aguja, falda o pierna): se vuelve tierna con la cocción larga. Dora la carne en tandas; si la amontonas, suelta líquido y se cuece en lugar de dorarse. Mantén siempre el fuego bajo: si hierve con fuerza, la carne queda dura. Si la salsa se reduce demasiado, añade un poco de caldo caliente. Mejora de un día para otro. Se conserva hasta 3 días en la nevera y se puede congelar hasta 3 meses, aunque las papas pierden algo de textura.","nutrition":{"calories":543,"protein_g":45.7,"carbs_g":30,"fat_g":26.5,"sodium_mg":869,"serving_size":"1 porción (1/4 de la receta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Suma de nutrientes por 100 g multiplicados por los pesos de los ingredientes y divididos entre 4 porciones. Se usan 800 g de carne de res cruda con su grasa, 110 g de cebolla, 9 g de ajo, 27 g de aceite de oliva, 16 g de pasta de tomate, 800 g de caldo de res, 450 g de papa, 240 g de zanahoria y 4 g de perejil. La sal, la pimienta, el laurel y el tomillo no se cuentan.","note":"Estimación por porción. La carne se calcula como aguja de res cruda con grasa, y el valor varía según el corte y la grasa que se retire. El caldo se calcula como caldo de res listo para tomar, y el sodio varía mucho según la marca. Se cuenta todo el aceite y todo el caldo aunque parte se evapore durante la cocción.","inputs":[{"fdc_id":"168634","description":"Beef, chuck, separable lean and fat, raw — proxy (800 g de carne de res en cubos)","grams":800,"per100":{"calories":170,"protein_g":20.0,"carbs_g":0,"fat_g":9.5,"saturated_fat_g":3.8,"fiber_g":0,"sodium_mg":68}},{"fdc_id":"170000","description":"Onions, raw (1 cebolla ≈ 110 g)","grams":110,"per100":{"calories":40,"protein_g":1.1,"carbs_g":9.34,"fat_g":0.1,"saturated_fat_g":0.042,"fiber_g":1.7,"sodium_mg":4}},{"fdc_id":"169230","description":"Garlic, raw (3 dientes ≈ 9 g)","grams":9,"per100":{"calories":149,"protein_g":6.36,"carbs_g":33.06,"fat_g":0.5,"saturated_fat_g":0.089,"fiber_g":2.1,"sodium_mg":17}},{"fdc_id":"171413","description":"Oil, olive, salad or cooking (2 cucharadas ≈ 27 g)","grams":27,"per100":{"calories":884,"protein_g":0,"carbs_g":0,"fat_g":100,"saturated_fat_g":13.81,"fiber_g":0,"sodium_mg":2}},{"fdc_id":"170459","description":"Tomato products, canned, paste, without salt added (1 cucharada ≈ 16 g)","grams":16,"per100":{"calories":82,"protein_g":4.32,"carbs_g":18.91,"fat_g":0.47,"saturated_fat_g":0.067,"fiber_g":4.1,"sodium_mg":59}},{"fdc_id":"172883","description":"Soup, beef broth, ready-to-serve (800 ml ≈ 800 g)","grams":800,"per100":{"calories":7,"protein_g":1.1,"carbs_g":0.1,"fat_g":0.2,"saturated_fat_g":0.08,"fiber_g":0,"sodium_mg":340}},{"fdc_id":"170026","description":"Potatoes, flesh and skin, raw (3 papas ≈ 450 g)","grams":450,"per100":{"calories":77,"protein_g":2.05,"carbs_g":17.49,"fat_g":0.09,"saturated_fat_g":0.026,"fiber_g":2.1,"sodium_mg":6}},{"fdc_id":"170393","description":"Carrots, raw (3 zanahorias ≈ 240 g)","grams":240,"per100":{"calories":41,"protein_g":0.93,"carbs_g":9.58,"fat_g":0.24,"saturated_fat_g":0.037,"fiber_g":2.8,"sodium_mg":69}},{"fdc_id":"170416","description":"Parsley, fresh (1 cucharada ≈ 4 g)","grams":4,"per100":{"calories":36,"protein_g":2.97,"carbs_g":6.33,"fat_g":0.79,"saturated_fat_g":0.132,"fiber_g":3.3,"sodium_mg":56}}]},"seo":{"title":"Estofado de res con papas y zanahorias | Manual de Cocina","description":"Estofado de res con papas y zanahorias, tierno y con salsa espesa, cocido a fuego lento. Para 4 personas, listo en 2 horas y 10 minutos. Receta paso a paso.","image_variants":["/recetas/estofado-de-res-con-papas-y-zanahorias/portada-1x1.webp","/recetas/estofado-de-res-con-papas-y-zanahorias/portada-4x3.webp","/recetas/estofado-de-res-con-papas-y-zanahorias/portada-16x9.webp"],"faq":[{"q":"¿Qué corte de carne es mejor para el estofado de res?","a":"Los cortes con algo de grasa y tejido conectivo, como la aguja, la falda o la pierna. Con la cocción lenta se vuelven tiernos y jugosos."},{"q":"¿Cuánto tiempo se cocina el estofado de res?","a":"En total unos 110 minutos de cocción: 8 para dorar y sofreír, 60 para la carne, 30 con las papas y las zanahorias y 10 para espesar la salsa."},{"q":"¿Se puede congelar el estofado de res?","a":"Sí, hasta 3 meses en un recipiente hermético. Las papas pierden algo de textura al descongelarse; descongela en la nevera y calienta a fuego bajo."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"e7771f99-3c4d-5c39-a447-72b8d6612105","recipe_group_id":"24670f80-3bbf-468c-b93a-6e1780efea48","language":"de","slug":"rindfleischeintopf-mit-kartoffeln-und-karotten","public_path":"/de/rindfleischeintopf-mit-kartoffeln-und-karotten","source_url":null,"title":"Rindfleischeintopf mit Kartoffeln und Karotten","excerpt":"Rindfleischeintopf mit Kartoffeln und Karotten, langsam geschmort, bis das Fleisch zart und die Sauce sämig ist. Für 4 Personen, fertig in 2 Stunden 10 Minuten.","summary":"Für den Rindfleischeintopf mit Kartoffeln und Karotten wird das gewürfelte Fleisch angebraten, mit Zwiebel, Knoblauch und Tomatenmark angeschwitzt und in Brühe mit Lorbeer und Thymian sanft geschmort, bis es zart ist. Danach kommen Kartoffeln und Karotten dazu, und die Sauce wird bei offenem Topf eingedickt.\n\nDer Eintopf braucht 2 Stunden 10 Minuten für Vorbereitung und Garen, das meiste davon ohne Aufsicht. Ergibt 4 Portionen.","category":"Hauptgerichte","difficulty":"Mittel","course":"Hauptgericht","cuisine":"Lateinamerikanisch","prep_time_minutes":20,"cook_time_minutes":110,"total_time_minutes":130,"servings":4,"keywords":["Rindfleischeintopf","Rindfleischeintopf mit Kartoffeln und Karotten","Rindfleischeintopf Rezept","Rindergulasch mit Kartoffeln","Rindfleisch schmoren","Eintopf mit Rindfleisch und Gemüse","estofado de res"],"ingredients":[{"name":"Rindfleisch zum Schmoren, gewürfelt","amount":"800","unit":"g","group":"Für den Eintopf"},{"name":"Zwiebel","amount":"1","unit":"","group":"Für den Eintopf"},{"name":"Knoblauchzehen","amount":"3","unit":"","group":"Für den Eintopf"},{"name":"Olivenöl","amount":"2","unit":"Esslöffel","group":"Für den Eintopf"},{"name":"Tomatenmark","amount":"1","unit":"Esslöffel","group":"Für den Eintopf"},{"name":"Rinderbrühe","amount":"800","unit":"ml","group":"Für den Eintopf"},{"name":"Lorbeerblatt","amount":"1","unit":"","group":"Für den Eintopf"},{"name":"Thymianzweig","amount":"1","unit":"","group":"Für den Eintopf"},{"name":"Salz","amount":"1","unit":"Teelöffel","group":"Für den Eintopf"},{"name":"schwarzer Pfeffer, gemahlen","amount":"1","unit":"Prise","group":"Für den Eintopf"},{"name":"Kartoffeln","amount":"3","unit":"","group":"Für das Gemüse"},{"name":"Karotten","amount":"3","unit":"","group":"Für das Gemüse"},{"name":"gehackte Petersilie","amount":"1","unit":"Esslöffel","group":"Zum Servieren"}],"steps":[{"title":"Zutaten vorbereiten","content":"800 g Rindfleischwürfel mit Küchenpapier trocken tupfen und mit 1 Teelöffel Salz und 1 Prise Pfeffer würzen. 1 Zwiebel und 3 Knoblauchzehen hacken, 3 Kartoffeln und 3 Karotten schälen und in große Stücke schneiden.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-01.webp","image_alt":"Rindfleischeintopf mit Kartoffeln und Karotten: Zutaten vorbereiten"},{"title":"Fleisch anbraten","content":"2 Esslöffel Öl in einem großen Topf bei mittelhoher Hitze erhitzen und das Fleisch portionsweise, ohne den Topf zu überfüllen, insgesamt 8 Minuten anbraten. Anschließend das gesamte Fleisch wieder in den Topf geben.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-02.webp","image_alt":"Rindfleischeintopf mit Kartoffeln und Karotten: Fleisch anbraten"},{"title":"Zwiebel und Knoblauch anschwitzen","content":"Die Hitze auf mittlere Stufe reduzieren, Zwiebel, Knoblauch und 1 Esslöffel Tomatenmark zugeben und unter Rühren 3 Minuten anschwitzen.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-03.webp","image_alt":"Rindfleischeintopf mit Kartoffeln und Karotten: Zwiebel und Knoblauch anschwitzen"},{"title":"Sanft schmoren","content":"800 ml Rinderbrühe zugießen, 1 Lorbeerblatt und 1 Thymianzweig zugeben, den Topf zudecken und bei niedriger Hitze 60 Minuten schmoren.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-04.webp","image_alt":"Rindfleischeintopf mit Kartoffeln und Karotten: Sanft schmoren"},{"title":"Gemüse zugeben","content":"Kartoffeln und Karotten zugeben, zudecken und weitere 30 Minuten garen, bis sie weich sind.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-05.webp","image_alt":"Rindfleischeintopf mit Kartoffeln und Karotten: Gemüse zugeben"},{"title":"Sauce eindicken","content":"Den Deckel abnehmen und 10 Minuten bei mittlerer bis niedriger Hitze köcheln, bis die Sauce sämig wird.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-06.webp","image_alt":"Rindfleischeintopf mit Kartoffeln und Karotten: Sauce eindicken"},{"title":"Abschmecken","content":"Mit Salz und Pfeffer abschmecken. Lorbeerblatt und Thymianzweig entfernen.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-07.webp","image_alt":"Rindfleischeintopf mit Kartoffeln und Karotten: Abschmecken"},{"title":"Servieren","content":"Heiß in tiefen Tellern servieren, mit 1 Esslöffel gehackter Petersilie bestreut.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-08.webp","image_alt":"Rindfleischeintopf mit Kartoffeln und Karotten: Servieren"}],"image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/portada.webp","gallery":[{"url":"/recetas/estofado-de-res-con-papas-y-zanahorias/portada.webp","alt":"Rindfleischeintopf mit Kartoffeln und Karotten"}],"notes":"Rindfleisch zum Schmoren mit etwas Fett und Bindegewebe wählen (Schulter, Bauchlappen oder Keule): Es wird beim langen Garen zart. Das Fleisch portionsweise anbraten; ist der Topf zu voll, tritt Flüssigkeit aus und es kocht, statt zu bräunen. Immer bei niedriger Hitze schmoren: Kocht es stark, wird das Fleisch zäh. Reduziert die Sauce zu stark, etwas heiße Brühe nachgießen. Schmeckt am nächsten Tag noch besser. Hält sich bis zu 3 Tage im Kühlschrank und lässt sich bis zu 3 Monate einfrieren, wobei die Kartoffeln etwas an Textur verlieren.","nutrition":{"calories":543,"protein_g":45.7,"carbs_g":30,"fat_g":26.5,"sodium_mg":869,"serving_size":"1 Portion (1/4 des Rezepts)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nährwerte je 100 g, multipliziert mit dem Gewicht der Zutaten und durch 4 Portionen geteilt. Verwendet werden 800 g rohes Rindfleisch mit Fett, 110 g Zwiebel, 9 g Knoblauch, 27 g Olivenöl, 16 g Tomatenmark, 800 g Rinderbrühe, 450 g Kartoffel, 240 g Karotte und 4 g Petersilie. Salz, Pfeffer, Lorbeer und Thymian werden nicht gezählt.","note":"Schätzung pro Portion. Das Fleisch wird als rohes Rindfleisch aus der Schulter mit Fett berechnet; der Wert hängt vom Stück und vom entfernten Fett ab. Die Brühe wird als trinkfertige Rinderbrühe berechnet, der Natriumwert schwankt je nach Marke stark. Das gesamte Öl und die gesamte Brühe werden gezählt, auch wenn ein Teil beim Garen verdampft."},"seo":{"title":"Rindfleischeintopf mit Kartoffeln und Karotten | Manual de Cocina","description":"Rindfleischeintopf mit Kartoffeln und Karotten, zart und mit sämiger Sauce, langsam geschmort. Für 4 Personen, fertig in 2 Stunden 10 Minuten. Rezept Schritt für Schritt.","image_variants":["/recetas/estofado-de-res-con-papas-y-zanahorias/portada-1x1.webp","/recetas/estofado-de-res-con-papas-y-zanahorias/portada-4x3.webp","/recetas/estofado-de-res-con-papas-y-zanahorias/portada-16x9.webp"],"faq":[{"q":"Welches Stück Rindfleisch eignet sich am besten für den Eintopf?","a":"Stücke mit etwas Fett und Bindegewebe, etwa Schulter, Bauchlappen oder Keule. Beim langsamen Garen werden sie zart und saftig."},{"q":"Wie lange gart der Rindfleischeintopf?","a":"Insgesamt etwa 110 Minuten: 8 zum Anbraten und Anschwitzen, 60 für das Fleisch, 30 mit Kartoffeln und Karotten und 10 zum Eindicken der Sauce."},{"q":"Kann man den Rindfleischeintopf einfrieren?","a":"Ja, bis zu 3 Monate in einem luftdichten Behälter. Die Kartoffeln verlieren beim Auftauen etwas an Textur; im Kühlschrank auftauen und bei niedriger Hitze erwärmen."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"ea895cfd-3ce3-57de-ac05-60058c4dfe16","recipe_group_id":"24670f80-3bbf-468c-b93a-6e1780efea48","language":"en","slug":"beef-stew-with-potatoes-and-carrots","public_path":"/en/beef-stew-with-potatoes-and-carrots","source_url":null,"title":"Beef Stew with Potatoes and Carrots","excerpt":"Beef stew with potatoes and carrots, slow-cooked until the meat is tender and the sauce is thick. Serves 4, ready in 2 hours 10 minutes.","summary":"Beef stew with potatoes and carrots is made by browning cubed beef, softening onion, garlic and tomato paste, and simmering the meat gently in stock with bay leaf and thyme until tender. The potatoes and carrots go in next, and the sauce is thickened by uncovering the pot.\n\nThe stew takes 2 hours 10 minutes from prep to table, most of it hands-off. It serves 4.","category":"Main dishes","difficulty":"Medium","course":"Main course","cuisine":"Latin American","prep_time_minutes":20,"cook_time_minutes":110,"total_time_minutes":130,"servings":4,"keywords":["beef stew","beef stew with potatoes and carrots","beef stew recipe","how to make beef stew","tender beef stew","slow cooked beef stew","estofado de res"],"ingredients":[{"name":"stewing beef, cubed","amount":"800","unit":"g","group":"For the stew"},{"name":"onion","amount":"1","unit":"","group":"For the stew"},{"name":"garlic cloves","amount":"3","unit":"","group":"For the stew"},{"name":"olive oil","amount":"2","unit":"tablespoon","group":"For the stew"},{"name":"tomato paste","amount":"1","unit":"tablespoon","group":"For the stew"},{"name":"beef stock","amount":"800","unit":"ml","group":"For the stew"},{"name":"bay leaf","amount":"1","unit":"","group":"For the stew"},{"name":"sprig of thyme","amount":"1","unit":"","group":"For the stew"},{"name":"salt","amount":"1","unit":"teaspoon","group":"For the stew"},{"name":"ground black pepper","amount":"1","unit":"pinch","group":"For the stew"},{"name":"potatoes","amount":"3","unit":"","group":"For the vegetables"},{"name":"carrots","amount":"3","unit":"","group":"For the vegetables"},{"name":"chopped parsley","amount":"1","unit":"tablespoon","group":"To serve"}],"steps":[{"title":"Prepare the ingredients","content":"Pat 800 g cubed beef dry with paper towels and season with 1 teaspoon salt and 1 pinch pepper. Chop 1 onion and 3 garlic cloves, and peel 3 potatoes and 3 carrots and cut them into large chunks.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-01.webp","image_alt":"Beef Stew with Potatoes and Carrots: Prepare the ingredients"},{"title":"Brown the beef","content":"Heat 2 tablespoons oil in a large pot over medium-high heat and brown the beef in batches, without crowding the pot, for 8 minutes in total. When done, return all the beef to the pot.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-02.webp","image_alt":"Beef Stew with Potatoes and Carrots: Brown the beef"},{"title":"Soften the onion and garlic","content":"Lower the heat to medium, add the onion, garlic and 1 tablespoon tomato paste, and cook for 3 minutes, stirring.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-03.webp","image_alt":"Beef Stew with Potatoes and Carrots: Soften the onion and garlic"},{"title":"Simmer gently","content":"Pour in 800 ml beef stock, add 1 bay leaf and 1 sprig of thyme, cover the pot and simmer over low heat for 60 minutes.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-04.webp","image_alt":"Beef Stew with Potatoes and Carrots: Simmer gently"},{"title":"Add the vegetables","content":"Add the potatoes and carrots, cover and cook for 30 minutes more, until tender.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-05.webp","image_alt":"Beef Stew with Potatoes and Carrots: Add the vegetables"},{"title":"Thicken the sauce","content":"Uncover the pot and cook for 10 minutes over medium-low heat, until the sauce thickens.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-06.webp","image_alt":"Beef Stew with Potatoes and Carrots: Thicken the sauce"},{"title":"Adjust the seasoning","content":"Taste and adjust the salt and pepper. Remove the bay leaf and the thyme sprig.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-07.webp","image_alt":"Beef Stew with Potatoes and Carrots: Adjust the seasoning"},{"title":"Serve","content":"Serve hot in shallow bowls, topped with 1 tablespoon chopped parsley.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-08.webp","image_alt":"Beef Stew with Potatoes and Carrots: Serve"}],"image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/portada.webp","gallery":[{"url":"/recetas/estofado-de-res-con-papas-y-zanahorias/portada.webp","alt":"Beef Stew with Potatoes and Carrots"}],"notes":"Choose a stewing cut with some fat and connective tissue (chuck, shin or round): it turns tender with long cooking. Brown the beef in batches; if you crowd the pot, it releases liquid and steams instead of browning. Keep the heat low throughout: if it boils hard, the meat turns tough. If the sauce reduces too much, add a little hot stock. It tastes even better the next day. It keeps up to 3 days in the fridge and can be frozen for up to 3 months, although the potatoes lose some texture.","nutrition":{"calories":543,"protein_g":45.7,"carbs_g":30,"fat_g":26.5,"sodium_mg":869,"serving_size":"1 serving (1/4 of the recipe)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Nutrients per 100 g multiplied by the weights of the ingredients and divided by 4 servings. It uses 800 g raw beef with its fat, 110 g onion, 9 g garlic, 27 g olive oil, 16 g tomato paste, 800 g beef stock, 450 g potato, 240 g carrot and 4 g parsley. Salt, pepper, bay leaf and thyme are not counted.","note":"Estimate per serving. The beef is calculated as raw chuck with fat, and the value varies with the cut and how much fat is trimmed. The stock is calculated as ready-to-serve beef broth, and sodium varies widely by brand. All the oil and all the stock are counted even if some evaporates during cooking."},"seo":{"title":"Beef Stew with Potatoes and Carrots | Manual de Cocina","description":"Beef stew with potatoes and carrots, tender with a thick sauce, slow-cooked. Serves 4, ready in 2 hours 10 minutes. Step-by-step recipe.","image_variants":["/recetas/estofado-de-res-con-papas-y-zanahorias/portada-1x1.webp","/recetas/estofado-de-res-con-papas-y-zanahorias/portada-4x3.webp","/recetas/estofado-de-res-con-papas-y-zanahorias/portada-16x9.webp"],"faq":[{"q":"What cut of beef is best for beef stew?","a":"Cuts with some fat and connective tissue, such as chuck, shin or round. With slow cooking they become tender and juicy."},{"q":"How long does beef stew take to cook?","a":"About 110 minutes of cooking in total: 8 for browning and softening, 60 for the beef, 30 with the potatoes and carrots and 10 to thicken the sauce."},{"q":"Can you freeze beef stew?","a":"Yes, for up to 3 months in an airtight container. The potatoes lose some texture when thawed; thaw in the fridge and reheat over low heat."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"b803f6da-8a5e-540a-9053-d9af99d27519","recipe_group_id":"24670f80-3bbf-468c-b93a-6e1780efea48","language":"fr","slug":"ragout-de-boeuf-aux-pommes-de-terre-et-carottes","public_path":"/fr/ragout-de-boeuf-aux-pommes-de-terre-et-carottes","source_url":null,"title":"Ragoût de bœuf aux pommes de terre et carottes","excerpt":"Ragoût de bœuf aux pommes de terre et carottes, mijoté doucement jusqu'à ce que la viande soit tendre et la sauce épaisse. Pour 4 personnes, prêt en 2 h 10.","summary":"Le ragoût de bœuf aux pommes de terre et carottes se prépare en faisant dorer la viande en cubes, en faisant revenir oignon, ail et concentré de tomate, puis en la laissant mijoter doucement dans le bouillon avec laurier et thym jusqu'à ce qu'elle soit tendre. On ajoute ensuite les pommes de terre et les carottes, et la sauce s'épaissit en découvrant la cocotte.\n\nLe ragoût demande 2 h 10 entre préparation et cuisson, presque sans surveillance. Pour 4 portions.","category":"Plats principaux","difficulty":"Moyenne","course":"Plat principal","cuisine":"Latino-américaine","prep_time_minutes":20,"cook_time_minutes":110,"total_time_minutes":130,"servings":4,"keywords":["ragoût de bœuf","ragoût de bœuf aux pommes de terre et carottes","recette ragoût de bœuf","comment faire un ragoût de bœuf","ragoût de bœuf tendre","bœuf mijoté aux légumes","estofado de res"],"ingredients":[{"name":"bœuf à mijoter, en cubes","amount":"800","unit":"g","group":"Pour le ragoût"},{"name":"oignon","amount":"1","unit":"","group":"Pour le ragoût"},{"name":"gousses d'ail","amount":"3","unit":"","group":"Pour le ragoût"},{"name":"huile d'olive","amount":"2","unit":"cuillère à soupe","group":"Pour le ragoût"},{"name":"concentré de tomate","amount":"1","unit":"cuillère à soupe","group":"Pour le ragoût"},{"name":"bouillon de bœuf","amount":"800","unit":"ml","group":"Pour le ragoût"},{"name":"feuille de laurier","amount":"1","unit":"","group":"Pour le ragoût"},{"name":"brin de thym","amount":"1","unit":"","group":"Pour le ragoût"},{"name":"sel","amount":"1","unit":"cuillère à café","group":"Pour le ragoût"},{"name":"poivre noir moulu","amount":"1","unit":"pincée","group":"Pour le ragoût"},{"name":"pommes de terre","amount":"3","unit":"","group":"Pour les légumes"},{"name":"carottes","amount":"3","unit":"","group":"Pour les légumes"},{"name":"persil haché","amount":"1","unit":"cuillère à soupe","group":"Pour servir"}],"steps":[{"title":"Préparer les ingrédients","content":"Éponger 800 g de bœuf en cubes avec du papier absorbant et l'assaisonner avec 1 cuillère à café de sel et 1 pincée de poivre. Hacher 1 oignon et 3 gousses d'ail, éplucher 3 pommes de terre et 3 carottes et les couper en gros morceaux.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-01.webp","image_alt":"Ragoût de bœuf aux pommes de terre et carottes: Préparer les ingrédients"},{"title":"Faire dorer la viande","content":"Chauffer 2 cuillères à soupe d'huile dans une grande cocotte à feu moyen-vif et faire dorer la viande en plusieurs fois, sans surcharger la cocotte, pendant 8 minutes au total. Remettre ensuite toute la viande dans la cocotte.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-02.webp","image_alt":"Ragoût de bœuf aux pommes de terre et carottes: Faire dorer la viande"},{"title":"Faire revenir l'oignon et l'ail","content":"Baisser à feu moyen, ajouter l'oignon, l'ail et 1 cuillère à soupe de concentré de tomate, et faire revenir 3 minutes en remuant.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-03.webp","image_alt":"Ragoût de bœuf aux pommes de terre et carottes: Faire revenir l'oignon et l'ail"},{"title":"Laisser mijoter doucement","content":"Verser 800 ml de bouillon de bœuf, ajouter 1 feuille de laurier et 1 brin de thym, couvrir la cocotte et laisser mijoter à feu doux 60 minutes.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-04.webp","image_alt":"Ragoût de bœuf aux pommes de terre et carottes: Laisser mijoter doucement"},{"title":"Ajouter les légumes","content":"Ajouter les pommes de terre et les carottes, couvrir et cuire 30 minutes de plus, jusqu'à ce qu'elles soient tendres.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-05.webp","image_alt":"Ragoût de bœuf aux pommes de terre et carottes: Ajouter les légumes"},{"title":"Épaissir la sauce","content":"Découvrir la cocotte et cuire 10 minutes à feu moyen-doux, jusqu'à ce que la sauce épaississe.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-06.webp","image_alt":"Ragoût de bœuf aux pommes de terre et carottes: Épaissir la sauce"},{"title":"Rectifier l'assaisonnement","content":"Goûter et rectifier le sel et le poivre. Retirer la feuille de laurier et le brin de thym.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-07.webp","image_alt":"Ragoût de bœuf aux pommes de terre et carottes: Rectifier l'assaisonnement"},{"title":"Servir","content":"Servir chaud dans des assiettes creuses, avec 1 cuillère à soupe de persil haché.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-08.webp","image_alt":"Ragoût de bœuf aux pommes de terre et carottes: Servir"}],"image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/portada.webp","gallery":[{"url":"/recetas/estofado-de-res-con-papas-y-zanahorias/portada.webp","alt":"Ragoût de bœuf aux pommes de terre et carottes"}],"notes":"Choisissez un morceau à mijoter avec un peu de gras et de tissu conjonctif (paleron, jarret ou gîte) : il devient tendre à la longue cuisson. Faites dorer la viande en plusieurs fois ; si la cocotte est trop pleine, elle rend de l'eau et cuit à l'étouffée au lieu de dorer. Gardez toujours un feu doux : si le ragoût bout fort, la viande durcit. Si la sauce réduit trop, ajoutez un peu de bouillon chaud. Il est encore meilleur le lendemain. Il se conserve jusqu'à 3 jours au réfrigérateur et se congèle jusqu'à 3 mois, mais les pommes de terre perdent un peu de texture.","nutrition":{"calories":543,"protein_g":45.7,"carbs_g":30,"fat_g":26.5,"sodium_mg":869,"serving_size":"1 portion (1/4 de la recette)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somme des nutriments pour 100 g multipliés par le poids des ingrédients et divisés par 4 portions. On utilise 800 g de bœuf cru avec son gras, 110 g d'oignon, 9 g d'ail, 27 g d'huile d'olive, 16 g de concentré de tomate, 800 g de bouillon de bœuf, 450 g de pomme de terre, 240 g de carotte et 4 g de persil. Le sel, le poivre, le laurier et le thym ne sont pas comptés.","note":"Estimation par portion. La viande est calculée comme du paleron de bœuf cru avec son gras, et la valeur varie selon le morceau et le gras retiré. Le bouillon est calculé comme un bouillon de bœuf prêt à consommer, et le sodium varie beaucoup selon la marque. Toute l'huile et tout le bouillon sont comptés même si une partie s'évapore à la cuisson."},"seo":{"title":"Ragoût de bœuf aux pommes de terre et carottes | Manual de Cocina","description":"Ragoût de bœuf aux pommes de terre et carottes, tendre et à la sauce épaisse, mijoté doucement. Pour 4 personnes, prêt en 2 h 10. Recette pas à pas.","image_variants":["/recetas/estofado-de-res-con-papas-y-zanahorias/portada-1x1.webp","/recetas/estofado-de-res-con-papas-y-zanahorias/portada-4x3.webp","/recetas/estofado-de-res-con-papas-y-zanahorias/portada-16x9.webp"],"faq":[{"q":"Quel morceau de bœuf choisir pour un ragoût ?","a":"Les morceaux avec un peu de gras et de tissu conjonctif, comme le paleron, le jarret ou le gîte. À la cuisson lente, ils deviennent tendres et juteux."},{"q":"Combien de temps cuit le ragoût de bœuf ?","a":"Environ 110 minutes de cuisson au total : 8 pour dorer et faire revenir, 60 pour la viande, 30 avec les pommes de terre et les carottes et 10 pour épaissir la sauce."},{"q":"Peut-on congeler le ragoût de bœuf ?","a":"Oui, jusqu'à 3 mois dans un récipient hermétique. Les pommes de terre perdent un peu de texture à la décongélation ; décongeler au réfrigérateur et réchauffer à feu doux."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"01c13206-4802-5992-8397-97373b25f388","recipe_group_id":"24670f80-3bbf-468c-b93a-6e1780efea48","language":"it","slug":"stufato-di-manzo-con-patate-e-carote","public_path":"/it/stufato-di-manzo-con-patate-e-carote","source_url":null,"title":"Stufato di manzo con patate e carote","excerpt":"Stufato di manzo con patate e carote, cotto lentamente finché la carne è tenera e il sugo denso. Per 4 persone, pronto in 2 ore e 10 minuti.","summary":"Lo stufato di manzo con patate e carote si prepara rosolando la carne a cubetti, soffriggendo cipolla, aglio e concentrato di pomodoro, e cuocendola a fuoco dolce nel brodo con alloro e timo finché è tenera. Poi si aggiungono patate e carote e il sugo si addensa scoprendo la pentola.\n\nLo stufato richiede 2 ore e 10 minuti tra preparazione e cottura, quasi tutti senza sorveglianza. Per 4 porzioni.","category":"Secondi piatti","difficulty":"Media","course":"Piatto principale","cuisine":"Latinoamericana","prep_time_minutes":20,"cook_time_minutes":110,"total_time_minutes":130,"servings":4,"keywords":["stufato di manzo","stufato di manzo con patate e carote","ricetta stufato di manzo","come fare lo stufato di manzo","stufato di manzo tenero","spezzatino di manzo con patate","estofado de res"],"ingredients":[{"name":"manzo da stufato, a cubetti","amount":"800","unit":"g","group":"Per lo stufato"},{"name":"cipolla","amount":"1","unit":"","group":"Per lo stufato"},{"name":"spicchi d'aglio","amount":"3","unit":"","group":"Per lo stufato"},{"name":"olio d'oliva","amount":"2","unit":"cucchiaio","group":"Per lo stufato"},{"name":"concentrato di pomodoro","amount":"1","unit":"cucchiaio","group":"Per lo stufato"},{"name":"brodo di manzo","amount":"800","unit":"ml","group":"Per lo stufato"},{"name":"foglia di alloro","amount":"1","unit":"","group":"Per lo stufato"},{"name":"rametto di timo","amount":"1","unit":"","group":"Per lo stufato"},{"name":"sale","amount":"1","unit":"cucchiaino","group":"Per lo stufato"},{"name":"pepe nero macinato","amount":"1","unit":"pizzico","group":"Per lo stufato"},{"name":"patate","amount":"3","unit":"","group":"Per le verdure"},{"name":"carote","amount":"3","unit":"","group":"Per le verdure"},{"name":"prezzemolo tritato","amount":"1","unit":"cucchiaio","group":"Per servire"}],"steps":[{"title":"Prepara gli ingredienti","content":"Asciuga 800 g di manzo a cubetti con carta da cucina e condiscilo con 1 cucchiaino di sale e 1 pizzico di pepe. Trita 1 cipolla e 3 spicchi d'aglio, sbuccia 3 patate e 3 carote e tagliale a pezzi grandi.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-01.webp","image_alt":"Stufato di manzo con patate e carote: Prepara gli ingredienti"},{"title":"Rosola la carne","content":"Scalda 2 cucchiai di olio in una pentola grande a fuoco medio-alto e rosola la carne a più riprese, senza affollarla, per 8 minuti in totale. Alla fine rimetti tutta la carne nella pentola.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-02.webp","image_alt":"Stufato di manzo con patate e carote: Rosola la carne"},{"title":"Soffriggi cipolla e aglio","content":"Abbassa a fuoco medio, aggiungi la cipolla, l'aglio e 1 cucchiaio di concentrato di pomodoro, e soffriggi per 3 minuti mescolando.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-03.webp","image_alt":"Stufato di manzo con patate e carote: Soffriggi cipolla e aglio"},{"title":"Cuoci a fuoco dolce","content":"Versa 800 ml di brodo di manzo, aggiungi 1 foglia di alloro e 1 rametto di timo, copri la pentola e cuoci a fuoco basso per 60 minuti.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-04.webp","image_alt":"Stufato di manzo con patate e carote: Cuoci a fuoco dolce"},{"title":"Aggiungi le verdure","content":"Unisci le patate e le carote, copri e cuoci per altri 30 minuti, finché sono tenere.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-05.webp","image_alt":"Stufato di manzo con patate e carote: Aggiungi le verdure"},{"title":"Addensa il sugo","content":"Scopri la pentola e cuoci per 10 minuti a fuoco medio-basso, finché il sugo si addensa.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-06.webp","image_alt":"Stufato di manzo con patate e carote: Addensa il sugo"},{"title":"Aggiusta di sapore","content":"Assaggia e aggiusta di sale e pepe. Elimina la foglia di alloro e il rametto di timo.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-07.webp","image_alt":"Stufato di manzo con patate e carote: Aggiusta di sapore"},{"title":"Servi","content":"Servi caldo nei piatti fondi, con 1 cucchiaio di prezzemolo tritato.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-08.webp","image_alt":"Stufato di manzo con patate e carote: Servi"}],"image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/portada.webp","gallery":[{"url":"/recetas/estofado-de-res-con-papas-y-zanahorias/portada.webp","alt":"Stufato di manzo con patate e carote"}],"notes":"Scegli un taglio da stufato con un po' di grasso e tessuto connettivo (spalla, muscolo o fesone): con la cottura lunga diventa tenero. Rosola la carne a più riprese; se affolli la pentola, rilascia liquido e si lessa invece di rosolare. Mantieni sempre la fiamma bassa: se bolle forte, la carne diventa dura. Se il sugo si restringe troppo, aggiungi un po' di brodo caldo. È ancora più buono il giorno dopo. Si conserva fino a 3 giorni in frigorifero e si può congelare fino a 3 mesi, anche se le patate perdono un po' di consistenza.","nutrition":{"calories":543,"protein_g":45.7,"carbs_g":30,"fat_g":26.5,"sodium_mg":869,"serving_size":"1 porzione (1/4 della ricetta)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei nutrienti per 100 g moltiplicati per i pesi degli ingredienti e divisi per 4 porzioni. Si usano 800 g di manzo crudo con il suo grasso, 110 g di cipolla, 9 g di aglio, 27 g di olio d'oliva, 16 g di concentrato di pomodoro, 800 g di brodo di manzo, 450 g di patata, 240 g di carota e 4 g di prezzemolo. Sale, pepe, alloro e timo non sono conteggiati.","note":"Stima per porzione. La carne è calcolata come spalla di manzo cruda con grasso, e il valore varia a seconda del taglio e del grasso eliminato. Il brodo è calcolato come brodo di manzo pronto, e il sodio varia molto a seconda della marca. Si conta tutto l'olio e tutto il brodo anche se una parte evapora durante la cottura."},"seo":{"title":"Stufato di manzo con patate e carote | Manual de Cocina","description":"Stufato di manzo con patate e carote, tenero e dal sugo denso, cotto lentamente. Per 4 persone, pronto in 2 ore e 10 minuti. Ricetta passo dopo passo.","image_variants":["/recetas/estofado-de-res-con-papas-y-zanahorias/portada-1x1.webp","/recetas/estofado-de-res-con-papas-y-zanahorias/portada-4x3.webp","/recetas/estofado-de-res-con-papas-y-zanahorias/portada-16x9.webp"],"faq":[{"q":"Quale taglio di manzo è meglio per lo stufato?","a":"I tagli con un po' di grasso e tessuto connettivo, come spalla, muscolo o fesone. Con la cottura lenta diventano teneri e succosi."},{"q":"Quanto cuoce lo stufato di manzo?","a":"In totale circa 110 minuti di cottura: 8 per rosolare e soffriggere, 60 per la carne, 30 con patate e carote e 10 per addensare il sugo."},{"q":"Si può congelare lo stufato di manzo?","a":"Sì, fino a 3 mesi in un contenitore ermetico. Le patate perdono un po' di consistenza quando si scongelano; scongela in frigorifero e riscalda a fuoco basso."}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"5bd8dd84-2513-540e-be8b-8b938fdc5788","recipe_group_id":"24670f80-3bbf-468c-b93a-6e1780efea48","language":"ja","slug":"牛肉とじゃがいもとにんじんの煮込み","public_path":"/ja/牛肉とじゃがいもとにんじんの煮込み","source_url":null,"title":"牛肉とじゃがいもとにんじんの煮込み","excerpt":"牛肉、じゃがいも、にんじんをじっくり煮込み、肉はやわらかく、ソースはとろりと仕上げます。4人分、2時間10分で完成。","summary":"牛肉とじゃがいもとにんじんの煮込みは、角切りの牛肉を焼きつけ、玉ねぎ、にんにく、トマトペーストを炒め、ローリエとタイムを加えたブイヨンで肉がやわらかくなるまで弱火で煮込んで作ります。そのあとじゃがいもとにんじんを加え、ふたを外してソースを煮つめます。\n\n下ごしらえから調理まで2時間10分、ほとんどは火にかけておくだけです。4人分です。","category":"主菜","difficulty":"普通","course":"主菜","cuisine":"ラテンアメリカ料理","prep_time_minutes":20,"cook_time_minutes":110,"total_time_minutes":130,"servings":4,"keywords":["牛肉の煮込み","牛肉とじゃがいもとにんじんの煮込み","牛肉 煮込み レシピ","牛肉 煮込み 作り方","やわらか 牛肉 煮込み","牛肉 野菜 煮込み","エストファード・デ・レス"],"ingredients":[{"name":"煮込み用の牛肉（角切り）","amount":"800","unit":"g","group":"煮込み用"},{"name":"玉ねぎ","amount":"1","unit":"","group":"煮込み用"},{"name":"にんにく","amount":"3","unit":"","group":"煮込み用"},{"name":"オリーブオイル","amount":"2","unit":"大さじ","group":"煮込み用"},{"name":"トマトペースト","amount":"1","unit":"大さじ","group":"煮込み用"},{"name":"牛のスープ（ブイヨン）","amount":"800","unit":"ml","group":"煮込み用"},{"name":"ローリエ","amount":"1","unit":"","group":"煮込み用"},{"name":"タイム","amount":"1","unit":"","group":"煮込み用"},{"name":"塩","amount":"1","unit":"小さじ","group":"煮込み用"},{"name":"黒こしょう（挽いたもの）","amount":"1","unit":"ひとつまみ","group":"煮込み用"},{"name":"じゃがいも","amount":"3","unit":"","group":"野菜用"},{"name":"にんじん","amount":"3","unit":"","group":"野菜用"},{"name":"パセリ（みじん切り）","amount":"1","unit":"大さじ","group":"仕上げ用"}],"steps":[{"title":"材料を準備する","content":"角切りの牛肉800gをキッチンペーパーで水気をふき、塩小さじ1とこしょうひとつまみで下味をつけます。玉ねぎ1個とにんにく3片をみじん切りに、じゃがいも3個とにんじん3本は皮をむいて大きめに切ります。","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-01.webp","image_alt":"牛肉とじゃがいもとにんじんの煮込み: 材料を準備する"},{"title":"牛肉を焼きつける","content":"大きめの鍋にオイル大さじ2を中強火で熱し、肉を鍋に詰め込みすぎないように数回に分けて、合計8分焼きつけます。焼き終えたら、肉をすべて鍋に戻します。","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-02.webp","image_alt":"牛肉とじゃがいもとにんじんの煮込み: 牛肉を焼きつける"},{"title":"玉ねぎとにんにくを炒める","content":"中火に下げ、玉ねぎ、にんにく、トマトペースト大さじ1を加えて、混ぜながら3分炒めます。","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-03.webp","image_alt":"牛肉とじゃがいもとにんじんの煮込み: 玉ねぎとにんにくを炒める"},{"title":"弱火で煮込む","content":"牛のスープ800mlを注ぎ、ローリエ1枚とタイム1枝を加え、ふたをして弱火で60分煮込みます。","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-04.webp","image_alt":"牛肉とじゃがいもとにんじんの煮込み: 弱火で煮込む"},{"title":"野菜を加える","content":"じゃがいもとにんじんを加え、ふたをしてやわらかくなるまでさらに30分煮ます。","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-05.webp","image_alt":"牛肉とじゃがいもとにんじんの煮込み: 野菜を加える"},{"title":"ソースを煮つめる","content":"ふたを外し、中弱火でソースがとろりとするまで10分煮ます。","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-06.webp","image_alt":"牛肉とじゃがいもとにんじんの煮込み: ソースを煮つめる"},{"title":"味をととのえる","content":"味見をして、塩とこしょうで味をととのえます。ローリエとタイムを取り除きます。","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-07.webp","image_alt":"牛肉とじゃがいもとにんじんの煮込み: 味をととのえる"},{"title":"盛り付ける","content":"深めの器に熱々をよそい、パセリのみじん切り大さじ1をのせます。","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-08.webp","image_alt":"牛肉とじゃがいもとにんじんの煮込み: 盛り付ける"}],"image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/portada.webp","gallery":[{"url":"/recetas/estofado-de-res-con-papas-y-zanahorias/portada.webp","alt":"牛肉とじゃがいもとにんじんの煮込み"}],"notes":"煮込み用には、脂身と結合組織が適度にある部位（肩ロース、すね肉、もも肉）を選ぶと、長時間煮込むことでやわらかくなります。肉は数回に分けて焼いてください。鍋に詰め込むと水分が出て、焼き色がつかず蒸し煮になります。火はずっと弱火に保ってください。強く沸騰させると肉がかたくなります。ソースが煮つまりすぎたら、温めたスープを少し足します。翌日にはさらにおいしくなります。冷蔵庫で3日間、冷凍で3か月保存できますが、じゃがいもは食感が少し落ちます。","nutrition":{"calories":543,"protein_g":45.7,"carbs_g":30,"fat_g":26.5,"sodium_mg":869,"serving_size":"1人分（レシピの1/4）","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"100gあたりの栄養素に材料の重量を掛け、4人分で割って合計しています。脂身つきの生の牛肉800g、玉ねぎ110g、にんにく9g、オリーブオイル27g、トマトペースト16g、牛のスープ800g、じゃがいも450g、にんじん240g、パセリ4gを使用しています。塩、こしょう、ローリエ、タイムは計算に含めていません。","note":"1人分の目安です。牛肉は脂身つきの生の肩肉として計算しており、部位や取り除く脂身の量によって値は変わります。スープはそのまま飲めるタイプの牛ブイヨンとして計算しており、ナトリウム量は商品によって大きく異なります。オイルとスープは、加熱中に蒸発する分も含めて全量を計算しています。"},"seo":{"title":"牛肉とじゃがいもとにんじんの煮込みの作り方 | Manual de Cocina","description":"牛肉、じゃがいも、にんじんをじっくり煮込んだ、やわらかくてとろみのある煮込み。4人分、2時間10分で完成。手順を写真付きで解説します。","image_variants":["/recetas/estofado-de-res-con-papas-y-zanahorias/portada-1x1.webp","/recetas/estofado-de-res-con-papas-y-zanahorias/portada-4x3.webp","/recetas/estofado-de-res-con-papas-y-zanahorias/portada-16x9.webp"],"faq":[{"q":"牛肉の煮込みにはどの部位が向いていますか？","a":"肩ロース、すね肉、もも肉のように、脂身と結合組織が適度にある部位です。じっくり煮込むとやわらかくジューシーになります。"},{"q":"牛肉の煮込みはどれくらい煮ますか？","a":"合計で約110分です。焼きつけと炒めに8分、肉の煮込みに60分、野菜を加えて30分、ソースを煮つめるのに10分かかります。"},{"q":"牛肉の煮込みは冷凍できますか？","a":"できます。密閉容器で3か月まで保存できます。じゃがいもは解凍すると食感が少し落ちます。冷蔵庫で解凍し、弱火で温め直してください。"}]},"published":true,"editorial_status":"published","content_html":""},
{"id":"5a2ded5d-029b-5b07-9837-941a5f2a4093","recipe_group_id":"24670f80-3bbf-468c-b93a-6e1780efea48","language":"pt","slug":"ensopado-de-carne-com-batata-e-cenoura","public_path":"/pt/ensopado-de-carne-com-batata-e-cenoura","source_url":null,"title":"Ensopado de carne com batata e cenoura","excerpt":"Ensopado de carne com batata e cenoura, cozido lentamente até a carne ficar macia e o molho encorpado. Para 4 pessoas, pronto em 2 horas e 10 minutos.","summary":"O ensopado de carne com batata e cenoura é feito dourando a carne em cubos, refogando cebola, alho e extrato de tomate, e cozinhando a carne em fogo baixo no caldo com louro e tomilho até ficar macia. Depois entram a batata e a cenoura, e o molho engrossa com a panela destampada.\n\nO ensopado leva 2 horas e 10 minutos entre preparo e cozimento, quase tudo sem supervisão. Rende 4 porções.","category":"Pratos principais","difficulty":"Média","course":"Prato principal","cuisine":"Latino-americana","prep_time_minutes":20,"cook_time_minutes":110,"total_time_minutes":130,"servings":4,"keywords":["ensopado de carne","ensopado de carne com batata e cenoura","receita de ensopado de carne","como fazer ensopado de carne","ensopado de carne macio","carne cozida com legumes","estofado de res"],"ingredients":[{"name":"carne bovina para ensopado, em cubos","amount":"800","unit":"g","group":"Para o ensopado"},{"name":"cebola","amount":"1","unit":"","group":"Para o ensopado"},{"name":"dentes de alho","amount":"3","unit":"","group":"Para o ensopado"},{"name":"azeite","amount":"2","unit":"colher de sopa","group":"Para o ensopado"},{"name":"extrato de tomate","amount":"1","unit":"colher de sopa","group":"Para o ensopado"},{"name":"caldo de carne","amount":"800","unit":"ml","group":"Para o ensopado"},{"name":"folha de louro","amount":"1","unit":"","group":"Para o ensopado"},{"name":"ramo de tomilho","amount":"1","unit":"","group":"Para o ensopado"},{"name":"sal","amount":"1","unit":"colher de chá","group":"Para o ensopado"},{"name":"pimenta-do-reino moída","amount":"1","unit":"pitada","group":"Para o ensopado"},{"name":"batatas","amount":"3","unit":"","group":"Para os legumes"},{"name":"cenouras","amount":"3","unit":"","group":"Para os legumes"},{"name":"salsinha picada","amount":"1","unit":"colher de sopa","group":"Para servir"}],"steps":[{"title":"Prepare os ingredientes","content":"Seque 800 g de carne em cubos com papel-toalha e tempere com 1 colher de chá de sal e 1 pitada de pimenta. Pique 1 cebola e 3 dentes de alho, descasque 3 batatas e 3 cenouras e corte em pedaços grandes.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-01.webp","image_alt":"Ensopado de carne com batata e cenoura: Prepare os ingredientes"},{"title":"Doure a carne","content":"Aqueça 2 colheres de sopa de azeite em uma panela grande em fogo médio-alto e doure a carne em etapas, sem amontoar, por 8 minutos no total. Ao terminar, volte toda a carne para a panela.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-02.webp","image_alt":"Ensopado de carne com batata e cenoura: Doure a carne"},{"title":"Refogue a cebola e o alho","content":"Baixe para fogo médio, junte a cebola, o alho e 1 colher de sopa de extrato de tomate e refogue por 3 minutos, mexendo.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-03.webp","image_alt":"Ensopado de carne com batata e cenoura: Refogue a cebola e o alho"},{"title":"Cozinhe em fogo baixo","content":"Despeje 800 ml de caldo de carne, junte 1 folha de louro e 1 ramo de tomilho, tampe a panela e cozinhe em fogo baixo por 60 minutos.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-04.webp","image_alt":"Ensopado de carne com batata e cenoura: Cozinhe em fogo baixo"},{"title":"Junte os legumes","content":"Adicione as batatas e as cenouras, tampe e cozinhe por mais 30 minutos, até ficarem macias.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-05.webp","image_alt":"Ensopado de carne com batata e cenoura: Junte os legumes"},{"title":"Engrosse o molho","content":"Destampe a panela e cozinhe por 10 minutos em fogo médio-baixo, até o molho engrossar.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-06.webp","image_alt":"Ensopado de carne com batata e cenoura: Engrosse o molho"},{"title":"Ajuste o tempero","content":"Prove e ajuste o sal e a pimenta. Retire a folha de louro e o ramo de tomilho.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-07.webp","image_alt":"Ensopado de carne com batata e cenoura: Ajuste o tempero"},{"title":"Sirva","content":"Sirva quente em pratos fundos, com 1 colher de sopa de salsinha picada por cima.","image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/paso-08.webp","image_alt":"Ensopado de carne com batata e cenoura: Sirva"}],"image_url":"/recetas/estofado-de-res-con-papas-y-zanahorias/portada.webp","gallery":[{"url":"/recetas/estofado-de-res-con-papas-y-zanahorias/portada.webp","alt":"Ensopado de carne com batata e cenoura"}],"notes":"Escolha um corte para ensopado, com um pouco de gordura e tecido conjuntivo (acém, peito ou coxão duro): ele fica macio com o cozimento longo. Doure a carne em etapas; se amontoar na panela, solta líquido e cozinha em vez de dourar. Mantenha sempre o fogo baixo: se ferver forte, a carne fica dura. Se o molho reduzir demais, junte um pouco de caldo quente. Fica ainda melhor no dia seguinte. Conserva-se até 3 dias na geladeira e pode ser congelado por até 3 meses, embora as batatas percam um pouco da textura.","nutrition":{"calories":543,"protein_g":45.7,"carbs_g":30,"fat_g":26.5,"sodium_mg":869,"serving_size":"1 porção (1/4 da receita)","estimated":true,"source":"USDA FoodData Central — SR Legacy (2018)","source_url":"https://fdc.nal.usda.gov/","method":"Soma dos nutrientes por 100 g multiplicados pelo peso dos ingredientes e divididos por 4 porções. Usam-se 800 g de carne bovina crua com gordura, 110 g de cebola, 9 g de alho, 27 g de azeite, 16 g de extrato de tomate, 800 g de caldo de carne, 450 g de batata, 240 g de cenoura e 4 g de salsinha. Sal, pimenta-do-reino, louro e tomilho não são contados.","note":"Estimativa por porção. A carne é calculada como acém cru com gordura, e o valor varia conforme o corte e a gordura retirada. O caldo é calculado como caldo de carne pronto para consumo, e o sódio varia muito conforme a marca. Todo o azeite e todo o caldo são contados, mesmo que parte evapore no cozimento."},"seo":{"title":"Ensopado de carne com batata e cenoura | Manual de Cocina","description":"Ensopado de carne com batata e cenoura, macio e com molho encorpado, cozido lentamente. Para 4 pessoas, pronto em 2 horas e 10 minutos. Receita passo a passo.","image_variants":["/recetas/estofado-de-res-con-papas-y-zanahorias/portada-1x1.webp","/recetas/estofado-de-res-con-papas-y-zanahorias/portada-4x3.webp","/recetas/estofado-de-res-con-papas-y-zanahorias/portada-16x9.webp"],"faq":[{"q":"Qual corte de carne é melhor para ensopado?","a":"Cortes com um pouco de gordura e tecido conjuntivo, como acém, peito ou coxão duro. No cozimento lento, ficam macios e suculentos."},{"q":"Quanto tempo leva para cozinhar o ensopado de carne?","a":"Cerca de 110 minutos de cozimento no total: 8 para dourar e refogar, 60 para a carne, 30 com as batatas e as cenouras e 10 para engrossar o molho."},{"q":"Dá para congelar o ensopado de carne?","a":"Dá, por até 3 meses em recipiente hermético. As batatas perdem um pouco de textura ao descongelar; descongele na geladeira e reaqueça em fogo baixo."}]},"published":true,"editorial_status":"published","content_html":""}
]$j$::jsonb;
  ts constant timestamptz := now();
  n int;
begin
  if (select count(*) from public.recipes where recipe_group_id = g) <> 1
     or not exists (select 1 from public.recipes where id = es_id and language = 'es' and published = false and public_path = '/estofado-de-res-con-papas-y-zanahorias') then
    raise exception 'Estado previo inesperado del grupo';
  end if;
  if exists (select 1 from public.recipes where id <> es_id and (public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)
      or (language, slug) in (select x->>'language', x->>'slug' from jsonb_array_elements(j) x))) then
    raise exception 'Colisión de slug/public_path';
  end if;
  if exists (select 1 from public.content_pages where public_path = any (select x->>'public_path' from jsonb_array_elements(j) x)) then
    raise exception 'Colisión con content_pages';
  end if;

  update public.recipes r set
    title = x.title, excerpt = x.excerpt, summary = x.summary, ingredients = x.ingredients, steps = x.steps,
    category = x.category, prep_time_minutes = x.prep_time_minutes, cook_time_minutes = x.cook_time_minutes,
    total_time_minutes = x.total_time_minutes, servings = x.servings, image_url = x.image_url,
    content_html = x.content_html, notes = x.notes, difficulty = x.difficulty, course = x.course,
    cuisine = x.cuisine, keywords = x.keywords, nutrition = x.nutrition, gallery = x.gallery, seo = x.seo,
    editorial_status = 'published', ready_at = ts, published = true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where r.id = es_id and x.language = 'es';
  get diagnostics n = row_count;
  if n <> 1 then raise exception 'UPDATE ES afectó % filas', n; end if;

  insert into public.recipes (id, recipe_group_id, language, slug, public_path, source_url, title, excerpt, summary,
    ingredients, steps, category, prep_time_minutes, cook_time_minutes, total_time_minutes, servings, image_url,
    content_html, notes, difficulty, course, cuisine, keywords, nutrition, gallery, seo, editorial_status, ready_at, published)
  select x.id, g, x.language, x.slug, x.public_path, null, x.title, x.excerpt, x.summary,
    x.ingredients, x.steps, x.category, x.prep_time_minutes, x.cook_time_minutes, x.total_time_minutes, x.servings, x.image_url,
    '', x.notes, x.difficulty, x.course, x.cuisine, x.keywords,
    x.nutrition || jsonb_build_object('inputs', (select nutrition->'inputs' from public.recipes where id = es_id)),
    x.gallery, x.seo, 'published', ts, true
  from jsonb_populate_recordset(null::public.recipes, j) x
  where x.language <> 'es';
  get diagnostics n = row_count;
  if n <> 6 then raise exception 'INSERT afectó % filas', n; end if;

  if (select count(*) from public.recipes where recipe_group_id = g and published and editorial_status = 'published'
        and language in ('es','de','en','fr','it','ja','pt')) <> 7 then
    raise exception 'El grupo no quedó con 7 filas publicadas';
  end if;
end
$pub$;
